const { AdminService } = require("../services/adminService");
const { JwtService } = require("../services/jwtService");

const ADMIN_EMAIL = (process.env.ADMIN_EMAIL || "").trim().toLowerCase();

/**
 * Middleware to authenticate Admin tokens
 * Checks JWT Bearer token generated by adminLogin (7h expiration)
 * Also retains backward compatibility with legacy tokens
 */
async function authenticateAdminToken(req, res, next) {
  try {
    const authHeader = req.headers.authorization;
    const adminEmailHeader = (req.headers["x-admin-email"] || req.headers["x-admin-user"] || "").trim().toLowerCase();

    // 1. Direct check for configured ADMIN_EMAIL from environment
    if (ADMIN_EMAIL && adminEmailHeader === ADMIN_EMAIL) {
      const master = await AdminService.findByEmail(ADMIN_EMAIL).catch(() => null);
      if (master) {
        req.admin = master;
        return next();
      }
    }

    // 2. Token header validation
    if (!authHeader || !authHeader.startsWith("Bearer ")) {
      return res.status(401).json({
        success: false,
        message: "Admin authorization token required (Bearer <token>)",
      });
    }

    const token = authHeader.split(" ")[1];
    if (!token) {
      return res.status(401).json({
        success: false,
        message: "Session token is required",
      });
    }

    let adminId = null;
    let email = null;

    // Check if it's a JWT token
    try {
      const decodedJwt = JwtService.verifyToken(token);
      adminId = decodedJwt.id;
      email = decodedJwt.email;
    } catch (jwtErr) {
      // Check if JWT has expired
      if (jwtErr.name === "TokenExpiredError") {
        return res.status(401).json({
          success: false,
          code: "TOKEN_EXPIRED",
          message: "Admin session has expired (7 hours limit). Please sign in again.",
        });
      }

      // Backward compatibility for legacy adm_token_ tokens
      if (token.startsWith("adm_token_")) {
        const encodedPart = token.replace("adm_token_", "");
        try {
          const decoded = Buffer.from(encodedPart, "base64").toString("utf8");
          const parts = decoded.split(":");
          adminId = parts[0];
          email = parts[1];
        } catch {
          return res.status(401).json({
            success: false,
            message: "Corrupted admin session token",
          });
        }
      } else {
        return res.status(401).json({
          success: false,
          message: "Invalid or expired admin session token",
        });
      }
    }

    if (!adminId && !email) {
      return res.status(401).json({
        success: false,
        message: "Invalid session claims",
      });
    }

    const cleanEmail = (email || "").trim().toLowerCase();

    // 3. Lookup administrator by ID or email from database
    let admin = adminId ? await AdminService.findById(adminId).catch(() => null) : null;
    if (!admin && cleanEmail) {
      admin = await AdminService.findByEmail(cleanEmail).catch(() => null);
    }

    // 4. Check if token belongs to environment superadmin
    if (!admin && ADMIN_EMAIL && cleanEmail === ADMIN_EMAIL) {
      admin = {
        id: adminId || "admin-env-master",
        email: ADMIN_EMAIL,
        name: "Primary Administrator",
        role: "super_admin",
        permissions: ["all"],
      };
    }

    if (!admin) {
      return res.status(401).json({
        success: false,
        message: "Administrator account no longer exists or access was revoked",
      });
    }

    req.admin = admin;
    next();
  } catch (err) {
    console.error("authenticateAdminToken error:", err);
    return res.status(500).json({
      success: false,
      message: "Server error during admin authentication check",
      error: err.message,
    });
  }
}

module.exports = {
  authenticateAdminToken,
};
